  assertRejected({ displayName: bad });
}

// tags: null or [] clears; trimming; distinctness after trimming; count and length bounds.
{
  const s = service();
  assert.deepEqual(s.patch({ tags: null }), { displayName: 'before', tags: [] });
  assert.deepEqual(s.patch({ tags: ['old'] }), { displayName: 'before', tags: ['old'] });
  assert.deepEqual(s.patch({ tags: [] }), { displayName: 'before', tags: [] });
  assert.deepEqual(s.patch({ tags: [' a ', 'b'] }).tags, ['a', 'b']);
  assert.deepEqual(s.patch({ tags: ['A', 'a'] }).tags, ['A', 'a']);
  assert.deepEqual(s.patch({ tags: ['1', '2', '3', '4', '5'] }).tags, ['1', '2', '3', '4', '5']);
  assert.deepEqual(s.patch({ tags: ['x'.repeat(12), '  ' + 'y'.repeat(12) + '  '] }).tags, ['x'.repeat(12), 'y'.repeat(12)]);
}
for (const bad of [
  ['a', 'b', 'c', 'd', 'e', 'f'],
  ['a', 'a'],
  ['a', ' a '],
  ['   '],
  [''],
  ['x'.repeat(13)],
  [' ' + 'x'.repeat(13) + ' '],
  [1],
  [null],
  [undefined],
  ['a', 2],
  'a',
  1,
  {},
  { length: 0 },
]) {
  assertRejected({ tags: bad });
}
{
  const sparse = new Array(2);
  sparse[1] = 'a';
  assertRejected({ tags: sparse });
}

// Unknown keys and invalid top-level shapes.
for (const bad of [null, undefined, 'x', 1, true, [], [{ displayName: 'x' }], () => {}, new Date(), new Map()]) {
  assert.throws(() => service().patch(bad), INVALID);
}
assertRejected({ displayName: 'ok', extra: 1 });
assertRejected({ tags: [], id: 1 });
assertRejected({ [Symbol('k')]: 1 });
assertRejected(Object.defineProperty({}, 'extra', { value: 1, enumerable: false }));
assertRejected(JSON.parse('{"__proto__": {"x": 1}}'));
assertRejected(Object.create({ displayName: 'inherited' }));
{
  class Patch {
    constructor() {
      this.displayName = 'x';
    }
  }
  assertRejected(new Patch());
}

// Accessor properties are rejected and their getters never run.
{
  let calls = 0;
  const input = {
    get displayName() {
      calls++;
      return 'x';
    },
  };
  assertRejected(input);
  assert.equal(calls, 0);
}

// Null-prototype objects are accepted.
{
  const s = service();
  const input = Object.create(null);
  input.displayName = 'Zed';
  input.tags = ['q'];
  assert.deepEqual(s.patch(input), { displayName: 'Zed', tags: ['q'] });
  assert.deepEqual(s.patch(Object.create(null)), { displayName: 'Zed', tags: ['q'] });
}

// A rejected field leaves the other, otherwise valid, field unapplied.
assertRejected({ displayName: 'ok', tags: [1] });
assertRejected({ displayName: 'ok', tags: ['a', 'a'] });

// The input is not mutated and its tags array is not stored.
{
  const s = service();
  const input = { displayName: '  Ada ', tags: [' a ', 'b'] };
  const snapshot = structuredClone(input);
  const result = s.patch(input);
  assert.deepEqual(input, snapshot);
  assert.deepEqual(result, { displayName: 'Ada', tags: ['a', 'b'] });

  const callerTags = ['keep'];
  s.patch({ tags: callerTags });
  assert.notEqual(s.profile.tags, callerTags);
  callerTags.push('later');
  assert.deepEqual(s.profile.tags, ['keep']);
}
